use Symfony\Config\MonologConfig;

return static function (MonologConfig $monolog): void {
    $monolog->handler('console')
        ->type('console')
        ->processPsr3Messages(false)
        ->channels()->elements(['!event', '!doctrine', '!console'])
    ;
};
